<section class="paper-card"><div class="section-title">{{$heading}}</div><div class="paper-body">@forelse($articles as $article)<article class="article"><div class="article-topline"><span class="badge text-bg-success">Original Article</span><span class="article-count">{{$article['count']??0}} downloads</span></div><a class="article-title d-block mt-3" target="_blank" rel="noopener" href="https://article.isarpublisher.com/viewArticle/{{$article['slug']??''}}">{{$article['name']??'Research article'}}</a><div class="article-meta"><span><i class="fa-solid fa-user"></i> {{$article['aname']??''}}</span><span><i class="fa-solid fa-bookmark"></i> {{$article['designation']??''}}</span><span><i class="fa-solid fa-book-open"></i> Page: {{$article['page']??'—'}}</span></div>@if(!empty($article['doi'])&&!in_array($article['doi'],['undefined','null']))<div class="article-doi"><i class="fa-solid fa-tag"></i> DOI: <a href="{{$article['doi']}}" target="_blank" rel="noopener">{{$article['doi']}}</a></div>@endif<div class="article-actions"><button class="btn btn-secondary btn-sm" data-bs-toggle="collapse" data-bs-target="#abstract-{{$article['id']??$loop->index}}"><i class="fa-solid fa-file-lines"></i> Abstract</button><a class="btn btn-secondary btn-sm" href="{{asset_url('articles/'.($article['file']??''))}}" target="_blank"><i class="fa-solid fa-file-pdf"></i> PDF</a><a class="btn btn-success btn-sm" target="_blank" rel="noopener" href="https://article.isarpublisher.com/viewArticle/{{$article['slug']??''}}">View Article <i class="fa-solid fa-circle-arrow-right"></i></a></div><div class="collapse abstract-box" id="abstract-{{$article['id']??$loop->index}}">{!!$article['abstract']??''!!}</div></article>@empty<div class="empty">No articles are available yet.</div>@endforelse</div></section>
